<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/js/bootstrap.bundle.min.js"></script><script>if('serviceWorker'in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));}function net(){let e=document.getElementById('netState');if(!e)return;e.textContent=navigator.onLine?'Онлайн':'Офлайн';e.className='badge '+(navigator.onLine?'text-bg-success':'text-bg-danger')}function qs(n){let e=document.getElementById('queueState');if(!e)return;e.textContent=n?'⏳ '+n:'';e.classList.toggle('d-none',!n)}window.addEventListener('online',net);window.addEventListener('offline',net);window.addEventListener('chist-queue',e=>qs(e.detail));net();try{qs(JSON.parse(localStorage.getItem('chist-attendance-queue')||'[]').length)}catch(e){}</script>@stack('scripts')</body></html>